select concat('#', id) as lid,  status, created_at, meta ->> 'journeyType' as journeyType, from tbl_customer_leads where partner_id = 'LOANS_24' and id not in(select lead_id from tbl_partner_callback_queue_logs where type = 'LEAD_CREATION' and product_id = 'CREDIT_CARD') order by created_at desc;

select l.partner_id as partner, concat('#', lead_id) as lead_id, concat('#', application_id) as application_id, *  from tbl_partner_callback_queue_logs as q JOIN tbl_customer_leads l ON q.lead_id = l.id and l.partner_id IN('SALARY_SE') and q.status = 'PENDING' and l.created_at::DATE > CURRENT_DATE - INTERVAL '1 months' order by l.created_at desc;

