WITH logData AS(SELECT l.lead_id,c.partner_id,l.status AS callbackStatus,c.status,l.created_at,ROW_NUMBER()OVER(PARTITION BY l.lead_id ORDER BY l.created_at DESC)AS row_number FROM tbl_customer_leads c INNER JOIN tbl_partner_callback_queue_logs l ON c.id=l.lead_id WHERE l.created_at BETWEEN'2023-01-28' AND'2024-08-28' AND c.status NOT IN('LEAD_INITIATED','NOT_INITIATED')AND l.product_id='CREDIT_CARD' AND c.partner_id IN('AIRTEL')),
leadData AS(select c.id as lead_id, c.partner_id, 'NOT_CREATED' as callbackStatus, c.status, c.created_at from tbl_customer_leads c where not exists (select 1 from tbl_partner_callback_queue_logs  where lead_id = c.id) and c.updated_at between '2023-01-26' and '2024-08-25' and c.status not in ('LEAD_INITIATED', 'NOT_INITIATED') and c.partner_id in ('AIRTEL'))

select partner_id, count(lead_id) as totalLead, count(CASE WHEN callbackStatus = 'PENDING' THEN 1 END) as totalPendingLead, count(CASE WHEN callbackStatus = 'DONE' THEN 1 END) as totalSendLead, count(CASE WHEN callbackStatus = 'NOT_CREATED' THEN 1 END) as totalNotCreateCallbackLeads FROM(
SELECT lead_id,partner_id,callbackStatus,status,created_at FROM logData WHERE row_number=1
UNION ALL
SELECT lead_id,partner_id,callbackStatus,status,created_at FROM leadData
) as result group by partner_id


\copy (WITH logData AS(SELECT l.lead_id,c.partner_id,l.status AS callbackStatus,c.status,l.created_at, count, error_details, ROW_NUMBER()OVER(PARTITION BY l.lead_id ORDER BY l.created_at DESC)AS row_number FROM tbl_customer_leads c INNER JOIN tbl_partner_callback_queue_logs l ON c.id=l.lead_id WHERE l.created_at::DATE>CURRENT_DATE-INTERVAL'3 day' AND c.status NOT IN('LEAD_INITIATED','NOT_INITIATED')AND l.product_id='CREDIT_CARD' AND c.partner_id IN('AIRTEL','VODAFONE','LOANS_24','DUMMY_PARTNER')),leadData AS(SELECT c.id AS lead_id,c.partner_id,'NOT_CREATED' AS callbackStatus,c.status,c.created_at FROM tbl_customer_leads c LEFT JOIN tbl_partner_callback_queue_logs l ON c.id=l.lead_id WHERE l.lead_id IS NULL AND c.updated_at::DATE>CURRENT_DATE-INTERVAL'3 day' AND c.status NOT IN('LEAD_INITIATED','NOT_INITIATED')AND c.partner_id IN('AIRTEL','VODAFONE','LOANS_24','DUMMY_PARTNER'))SELECT lead_id,partner_id,callbackStatus,status,created_at, count, error_details FROM logData WHERE row_number=1 UNION ALL SELECT lead_id,partner_id,callbackStatus,status,created_at, 0 as count, null as error_details FROM leadData)  to '/home/ubuntu/csv-dump/leads_callbacks_20240828.csv' DELIMITER ',' CSV header;


